const cfgRes = $('Odoo: get config').first().json;
if (cfgRes.error || !cfgRes.result) throw new Error('Odoo config not found. Check ODOO_* env vars and sunguard_crm.ids.');
const cfg = JSON.parse(cfgRes.result);
const context = { allowed_company_ids: [cfg.company_id] };

// Hot/Warm leads that were processed by A1 and have no reply yet. Max per run keeps Gemini use small.
const MAX = 3;
// Header names are trimmed so a stray space in a sheet header does not break the match.
const tidy = (o) => Object.fromEntries(Object.entries(o).map(([k, v]) => [String(k).trim(), v]));
const rows = $input.all().map(i => tidy(i.json)).filter(r =>
  String(r.Status || '').trim() === 'Processed' && ['Hot', 'Warm'].includes(String(r.Score || '').trim()) &&
  !String(r.Reply_Status || '').trim() && String(r.Odoo_Lead_ID || '').trim()).slice(0, MAX);
if (!rows.length) return [];
const ids = [...new Set(rows.map(r => Number(r.Odoo_Lead_ID)))];
return [{ json: { rows, rpc: { model: 'crm.lead', method: 'search_read', args: [[['id', 'in', ids]]],
  kwargs: { fields: ['id', 'name', 'tag_ids'], context } } } }];

